// Elecnova product configs for the E-Systems "ess-cabinet" 3D catalog engine (same schema as the Bluesun catalog).
// Dimensions and specs: elecnova-ess.com product pages, Elecnova datasheets / manuals, "Каталог ESS.pdf",
// "Elecnova Price List.xlsx" (EXW Rotterdam). Layouts inside cabinets: manual photos where available, else schematic.

const BRAND = 'Elecnova';
const COLORS = {
  shell: '#EEF0F2', roof: '#E6E9EC', plinth: '#2F353B', door: '#F3F5F6', doorIn: '#E3E7EA', frame: '#D3D9DD',
  accent: '#1E4C9A', module: '#D5DADE', modFace: '#C9CFD4', hv: '#9AA4AB', pcs: '#B7BFC5', chiller: '#C2C9CE',
  dist: '#D9DEE2', inv: '#F1F3F4', cab: '#E2E6E9', coil: '#3F5566', duct: '#CBD2D6',
};
const base = (extra = {}) => ({
  template: 'ess-cabinet', brand: BRAND, theme: { brand: '#1E4C9A' },
  logo: { type: 'plain', text: 'Elecnova', color: '#1E4C9A' }, colors: { ...COLORS, ...(extra.colors || {}) },
});
const eyes = (w, d) => [-1, 1].flatMap(sx => [-1, 1].map(sz => ({ type: 'eye', x: sx * (w / 2 - 0.1), z: sz * (d / 2 - 0.1) })));
const fmt = n => String(n).replace('.', ',');
const LEDS = ['#2EE07A', '#F2C230', '#E8392B'];
const SRC_SITE = id => `сторінка товару elecnova-ess.com/${id}`;

// ---------- common texts ----------
const CELL314 = (series, v) => ({ name: 'Комірка LFP 314 А·год', text: `Призматична комірка LFP. ${series} комірок послідовно дають ${v} В.`, kv: [['Ємність', '314 А·год'], ['Номінальна напруга', '3,2 В'], ['Ресурс', '≥ 8 000 циклів (даташит шафи)']] });
const CELL280 = (series, v) => ({ name: 'Комірка LFP 280 А·год', text: `Призматична комірка LFP. ${series} комірок послідовно дають ${v} В.`, kv: [['Ємність', '280 А·год'], ['Номінальна напруга', '3,2 В']] });
const CELL120 = (series, v) => ({ name: 'Комірка LFP 120 А·год', text: `Комірка LFP 120 А·год. ${series} комірок послідовно дають ${v} В.`, kv: [['Ємність', '120 А·год'], ['Номінальна напруга', '3,2 В']] });
const FIRE_INFO = (extra = '') => ({ name: 'Пожежна безпека', short: 'Пожежогасіння', text: `Раннє попередження (дим, температура) і аерозольне гасіння${extra}. Запустіть тест, щоб побачити спрацювання.`, kv: [['Засіб гасіння', 'аерозоль'], ['Датчики', 'дим, температура']] });
const EMS_INFO = { name: 'Локальний контролер BCQ (EMS)', short: 'BCQ', text: 'Локальний EMS-контролер шафи (BCQ): збирає дані BMS, PCS, HVAC і пожежної системи, керує режимами. Зв\'язок з EMS верхнього рівня по Modbus TCP/IP. Кількома шафами й STS на об\'єкті може керувати EMS E-Systems.', kv: [['Зв\'язок', 'Modbus TCP/IP'], ['Моніторинг', 'HMI на шафі, APP / web']] };
const estopInfo = { name: 'Аварійна кнопка', text: 'Аварійне відключення шафи на дверях; поруч індикатори роботи.', kv: [] };

function fireCab(w, d, h, extra = []) {
  return {
    items: [
      { type: 'aerosol', pos: [-w * 0.18, h - 0.22, 0.1], r: 0.05, len: 0.3, label: 'Аерозольний генератор шафи', left: true, pin: [0, 0.08, 0] },
      { type: 'smoke', pos: [w * 0.22, h - 0.12, d * 0.2], label: 'Датчик диму', pin: [0, -0.08, 0] },
      { type: 'heat', pos: [w * 0.05, h - 0.12, -d * 0.2], label: 'Датчик температури', pin: [0, -0.07, 0] },
      ...extra,
      { type: 'led', index: 2, label: 'Індикатор аварії на дверях', pin: [0.05, 0.03, 0.02] },
      { type: 'estop', label: 'Аварійна кнопка', pin: [0, -0.06, 0.02] },
    ], alarmLeds: [2],
  };
}
const packAerosol = (x, y, z, label = 'Аерозоль у кожному пакеті (PACK-level)') => ({ type: 'aerosol', vertical: true, pos: [x, y, z], r: 0.03, len: 0.18, label, pin: [0.04, 0.1, 0] });

// ---------- application (apply) helpers ----------
const usesCabinet = (kw, kwh) => {
  const h = (kwh * 0.9 / kw).toFixed(1).replace('.', ',');
  return [
    ['Peak shaving і тарифи', 'Заряд у нічний тариф або від СЕС, розряд у пікові години; EMS тримає імпорт з мережі під заданою межею.', 'e'],
    ['Резерв з STS', 'PCS шафи працює автономно; безперервне живлення критичного навантаження (< 20 мс) дає шафа STS Elecnova.', 'b'],
    ['Тривалість резерву', `≈ ${h} год при ${kw} кВт (90 % ємності, без урахування ККД).`, 'e'],
    ['Масштабування', 'Шафи з\'єднуються паралельно на стороні змінного струму.', 'b'],
  ];
};

