// ---------------- helpers for two-door liquid family ----------------
function twoDoor({ w, d, h, packs, pitch = 0.24, mod = { w: 0.84, h: 0.21, d: 1.1 }, label = 'ELECNOVA', hasPcs = true, hmi = true }) {
  const xs = -w / 2 + 0.32;               // split between narrow left door and main door
  const left = { hinge: 'left', x0: -w / 2 + 0.005, x1: xs - 0.005, items: [
    { type: 'grille', style: 'louver', x: (xs + w / 2) / 2 - 0.005, y: h - 0.55, w: 0.2, h: 0.62 },
    { type: 'grille', style: 'louver', x: (xs + w / 2) / 2 - 0.005, y: 0.55, w: 0.2, h: 0.62 },
    { type: 'handle', x: xs + w / 2 - 0.05, y: 1.15, h: 0.2 }] };
  const mw = w / 2 - xs;
  const right = { hinge: 'right', x0: xs + 0.005, x1: w / 2 - 0.005, items: [
    { type: 'stripe', x: 0.08, w: 0.14, y: h - 0.62, h: 0.95 },
    { type: 'logo', x: mw * 0.55, y: h - 0.2, w: 0.24, h: 0.06 },
    ...(hmi ? [{ type: 'slot', x: mw * 0.55, y: h - 0.45, w: 0.14, h: 0.14 },
      { type: 'leds', pts: [[mw * 0.55, h - 0.66], [mw * 0.55, h - 0.71], [mw * 0.55, h - 0.76]], colors: LEDS, r: 0.011 },
      { type: 'estop', x: mw * 0.55, y: h - 0.92 }] : [{ type: 'slot', x: mw * 0.55, y: h - 0.7, w: 0.3, h: 0.24 }, { type: 'leds', pts: [[mw * 0.5, h - 0.95], [mw * 0.55, h - 0.95], [mw * 0.6, h - 0.95]], colors: LEDS, r: 0.011 }, { type: 'estop', x: mw * 0.55, y: h - 1.07 }]),
    { type: 'line', x: mw * 0.55, y: h - 1.2, w: mw * 0.8, mat: 'accent' },
    { type: 'warn', x: mw * 0.55, y: 0.35 },
    { type: 'handle', x: mw - 0.06, y: 1.15, h: 0.22 },
    { type: 'ems', x: mw * 0.55, y: h - 0.6 }] };
  const rx = (xs + w / 2) / 2;
  const top = 0.25 + pitch * (packs - 1) + mod.h / 2;
  return {
    cabinet: { w, d, h, floor: 0.12, roof: 0.05, partitions: [{ x: xs }], roofItems: eyes(w, d), doors: [left, right] },
    rack: { count: packs, y0: hasPcs ? 0.62 : 0.3, pitch, x: rx, z: -0.04, module: { ...mod, face: 'label', label }, cell: { w: 0.168, h: mod.h - 0.03, d: 0.068, px: 0.174, pz: 0.08, cols: 4, rows: 13 }, explode: [0, 0.22, 0.13, 1.6] },
    left: { x: (-w / 2 + xs) / 2, wid: xs + w / 2 - 0.04 }, rx, top,
  };
}

