  c.cooling = cool;
  c.cabinet.door.items = [
    { type: 'stripe', x: 0.08, w: 0.14, y: h - 0.6, h: 0.9 }, { type: 'logo', x: w * 0.55, y: h - 0.2, w: 0.26, h: 0.065 },
    { type: 'slot', x: w * 0.55, y: h - 0.5, w: 0.16, h: 0.16 }, { type: 'leds', pts: [[w * 0.5, h - 0.75], [w * 0.55, h - 0.75], [w * 0.6, h - 0.75]], colors: LEDS, r: 0.011 },
    { type: 'estop', x: w * 0.55, y: h - 0.9 }, { type: 'line', x: w * 0.55, y: h - 1.1, w: w * 0.8, mat: 'accent' },
    { type: 'grille', style: 'louver', x: w * 0.55, y: 0.55, w: w * 0.7, h: 0.6 }, { type: 'warn', x: w * 0.55, y: 0.98 }, { type: 'handle', x: w - 0.06, y: 1.1, h: 0.22 }];
