  c.units = [{ ...c.units[0], pos: [0, h - 0.22, -0.1], size: [w - 0.3, 0.16, 0.5] }, { ...c.units[1], size: [0.32, 0.9, 0.7], pos: [w / 2 + 0.2, 1.4, 0.15] }];
  c.info.door = { name: 'Двері та корпус', text: 'Вулична шафа IP55 на фундаменті; гібридний інвертор на боковій стінці.', kv: [['Шафа Ш × Г × В', `${w * 1000} × ${d * 1000} × ${h * 1000} мм`], ['Разом з інвертором', `${entire} мм`]] };
  c.rows = c.rows.map(r => r[0] === 'door' ? ['door', 'Двері та корпус'] : r);
